insert into recordare.products (id, cat, name_pt, name_en, desc_pt, desc_en, badge_pt, badge_en, price, unit, img, sizes, colors, finishes, rating, reviews, slot) values
  ('p1', 'medalhoes', 'Medalhão Oval Clássico', 'Classic Oval Medallion', 'Fotoporcelana oval de alta durabilidade para lápides, resistente ao sol e à chuva. Impressão vitrificada em forno a 820°C, garantia de 20 anos.', 'High-durability oval photo porcelain for headstones, sun- and rain-resistant. Vitrified print fired at 820°C, 20-year guarantee.', 'Mais vendido', 'Bestseller', 249.0, 'un', 'https://commons.wikimedia.org/wiki/Special:FilePath/Louisa%20May%20Alcott%2C%20c.%201870%20-%20Warren%27s%20Portraits%2C%20Boston.jpg?width=700', ARRAY['13x18','18x24','24x30']::text[], ARRAY['branco','marfim']::text[], ARRAY['fosco','brilhante']::text[], 4.9, 128, 'p1-main'),
  ('p2', 'lapides', 'Placa Retangular Memória', 'Rectangular Memory Plaque', 'Placa em porcelana sobre granito com foto, nome e datas gravados. Ideal para lápides e memoriais permanentes.', 'Porcelain-on-granite plaque with engraved photo, name and dates. Ideal for headstones and permanent memorials.', null, null, 299.0, 'un', 'https://commons.wikimedia.org/wiki/Special:FilePath/Edith%20Kermit%20Carow%20Roosevelt%20by%20Frances%20Benjamin%20Johnston%20%28cropped%29.jpg?width=700', ARRAY['18x24','24x30','30x40']::text[], ARRAY['branco','marfim','preto']::text[], ARRAY['fosco','brilhante']::text[], 4.8, 74, 'p2-main'),
  ('p3', 'porcelanato', 'Porcelanato Capela 60×60', 'Chapel Porcelain Tile 60×60', 'Porcelanato retificado para capelas, jazigos e memoriais. Alta resistência e fácil limpeza.', 'Rectified porcelain tile for chapels, tombs and memorials. Highly durable and easy to clean.', 'Sob medida', 'Custom', 189.0, 'm2', 'https://commons.wikimedia.org/wiki/Special:FilePath/Beige%20cream%20marble%20diagonal%20diamond%20pattern%20seamless%20tiled%20floor%20paving%20texture.jpg?width=700', ARRAY['60x60','80x80','120x120']::text[], ARRAY['branco','cinza']::text[], ARRAY['fosco','acetinado','brilhante']::text[], 4.7, 56, 'p3-main'),
  ('p4', 'lapides', 'Placa Dupla Família', 'Double Family Plaque', 'Placa memorial com dois medalhões ovais integrados, para homenagear o casal ou a família.', 'Memorial plaque with two integrated oval medallions, honoring a couple or family.', null, null, 389.0, 'un', 'https://commons.wikimedia.org/wiki/Special:FilePath/Emmeline%20Pankhurst%2C%20seated%20%281913%29.jpg?width=700', ARRAY['24x30','30x40']::text[], ARRAY['branco','marfim']::text[], ARRAY['fosco','brilhante']::text[], 5.0, 41, 'p4-main'),
  ('p5', 'lapides', 'Placa Epitáfio Personalizada', 'Custom Epitaph Plaque', 'Placa em porcelana com epitáfio, versículo ou mensagem gravada. Fixação parafusada ou adesiva.', 'Porcelain plaque with engraved epitaph, verse or message. Screw or adhesive mounting.', 'Novo', 'New', 159.0, 'un', 'https://commons.wikimedia.org/wiki/Special:FilePath/Alice%20C.%20Evans%2C%20National%20Photo%20Company%20portrait%2C%20circa%201915.jpg?width=700', ARRAY['15x20','20x30']::text[], ARRAY['branco','preto']::text[], ARRAY['fosco','brilhante']::text[], 4.6, 212, 'p5-main'),
  ('p6', 'lapides', 'Lápide Completa em Granito', 'Complete Granite Headstone', 'Lápide completa em granito com medalhão fotoporcelana, gravação de nome, datas e ornamentos.', 'Complete granite headstone with photo-porcelain medallion, engraved name, dates and ornaments.', null, null, 1290.0, 'un', 'https://commons.wikimedia.org/wiki/Special:FilePath/Pale%20grey%20granite%20rock%20seamless%20stone%20surface%20texture.jpg?width=700', ARRAY['60x40','70x50']::text[], ARRAY['preto','cinza']::text[], ARRAY['fosco','brilhante']::text[], 4.8, 37, 'p6-main'),
  ('p7', 'acessorios', 'Vaso Memorial Porcelana', 'Memorial Porcelain Vase', 'Vaso de porcelana com fotoporcelana integrada, acabamento artesanal para flores no memorial.', 'Porcelain vase with integrated photo porcelain, handcrafted finish for memorial flowers.', null, null, 419.0, 'un', 'https://commons.wikimedia.org/wiki/Special:FilePath/Lucretia%20Mott%2C%20signed%20photo%2C%20by%20F.%20Gutekunst.jpg?width=700', ARRAY['P','M','G']::text[], ARRAY['branco','marfim']::text[], ARRAY['fosco','brilhante']::text[], 4.9, 38, 'p7-main'),
  ('p8', 'medalhoes', 'Medalhão Redondo Porcelana', 'Round Porcelain Medallion', 'Medalhão redondo com moldura em porcelana branca, para lápides e nichos. Impressão de alta fidelidade.', 'Round medallion with white porcelain frame for headstones and niches. High-fidelity printing.', null, null, 129.0, 'un', 'https://commons.wikimedia.org/wiki/Special:FilePath/Ida%20M.%20Tarbell.jpg?width=700', ARRAY['9cm','11cm']::text[], ARRAY['branco','marfim']::text[], ARRAY['brilhante']::text[], 4.7, 96, 'p8-main'),
  ('p9', 'porcelanato', 'Porcelanato Mármore Retrato 80×80', 'Marble Portrait Tile 80×80', 'Porcelanato com efeito mármore e retrato integrado. Peça de destaque para jazigos e mausoléus.', 'Marble-effect porcelain tile with integrated portrait. A statement piece for tombs and mausoleums.', 'Premium', 'Premium', 229.0, 'm2', 'https://commons.wikimedia.org/wiki/Special:FilePath/Cream%20ivory%20beige%20marble%20vertical%20straight%20stack%20seamless%20tile%20floor%20paving%20texture.jpg?width=700', ARRAY['80x80','120x120']::text[], ARRAY['branco','cinza']::text[], ARRAY['acetinado','brilhante']::text[], 4.9, 29, 'p9-main'),
  ('p10', 'medalhoes', 'Medalhão Oval Bronze', 'Bronze Oval Medallion', 'Medalhão com moldura em bronze e fotoporcelana central. Fixação parafusada ou adesiva.', 'Medallion with bronze frame and central photo porcelain. Screw or adhesive mounting.', null, null, 189.0, 'un', 'https://commons.wikimedia.org/wiki/Special:FilePath/Elizabeth%20Glendower%20Evans%20%28cropped%29.jpg?width=700', ARRAY['9x12','11x15']::text[], ARRAY['marfim']::text[], ARRAY['fosco','brilhante']::text[], 4.8, 64, 'p10-main')
